window.__HOT_STORIES__ = {"schemaVersion":1,"updatedAt":"2026-10-25T16:32:05.039Z","stories":{"6cbe9dba-8fec-42b1-92ab-5a9ccf944190":{"publicId":"6cbe9dba-8fec-42b1-92ab-5a9ccf944190","title":"月之暗面发布 Kimi K3.1 Pro，权重定于 11 月 4 日前释出","status":"active","sourceCount":24,"reportCount":42,"firstReportAt":"2026-10-22T16:00:00.000Z","latestAt":"2026-10-24T12:14:49.000Z","latest":"Nathan Lambert 谈模型真实可用性比 AA 分数更重要","digest":"月之暗面发布 Kimi K3.1 系列首个模型 Kimi K3.1 Pro，称其为最强 3T 级开放权重模型：MoE 总参数 2.8T、激活 104B，支持 1M token 上下文和多模态，已上线 Kimi.ai、Kimi Work、Kimi Code 和 API，速度约 2–3 倍的 Highspeed 版同步推出。完整权重尚未发布，官方承诺 2026 年 11 月 4 日前释出；企业端默认关闭，需管理员开启。\n\n第三方评测显示其接近闭源前沿：Artificial Analysis Intelligence Index 得 55 分列第 4，较 Kimi K3 提升 11 分，仅低于 Claude Opus 5.5（58）、Claude Sonnet 5.5 和 Muse Wonder Full（均 56）；Code Arena: WebDev 以 1692 分排第 8，与 Claude Opus-5 (Max) 持平而成本低 70%。Nathan Lambert 称，若权重如期开放，它将是最高分开源权重模型；但他随后表示，顶级模型层面真实可用性比 AA 分数差距更重要，K3.1“可能更偏向未能兑现的一侧”。\n\n定价为每百万 token 输入 2 美元、输出 10 美元、缓存命中 0.2 美元，三项均比 K3 低 33%；Lambert 提醒其每回答 token 用量明显更多，实际花费可能相近。月之暗面称在开放权重前刻意削弱了网络攻击能力，内部漏洞利用基准 pass@3 从 90.5% 降至 81.0%。腾讯 WorkBuddy 已接入该模型及 Highspeed 版，现阶段仅向企业旗舰版和个人订阅用户优先开放。","digestUpdatedAt":"2026-10-24T12:38:13.044Z","reports":[{"id":"cd07y2cta070sthy7b41i2ycc","title":"DeepSeek 传融资约 150 亿美元，月之暗面发布 Kimi K3.1 Pro，中国出台 AI 就业政策","summary":"月之暗面发布 Kimi K3.1 Pro，支持 100 万 token 上下文窗口，并推出速度快 2-3 倍的 Highspeed 版本，Terminal-Bench 4.0 得分 65.7%，模型权重计划 11 月 4 日前开放。","sourceName":"Recode China AI（RSS）","firstParty":false,"publishedAt":"2026-10-25T14:46:37.000Z","url":"https://www.recodechinaai.com/p/deepseeks-15b-round-its-38gpu-hour"},{"id":"db7o2n2i3ktwkfgl7bisyeht2","title":"Nathan Lambert 谈模型真实可用性比 AA 分数更重要","summary":"在顶级模型层面，真实世界的可用性远比 AA 上 +/- 2 分的差距重要得多。一个模型需要花一段时间才能理解这一点，AA 在某种程度上是一种潜力，但有些模型能兑现，有些则不能（例如 opus 5 与 5.5）。看起来 3.1 可能更偏向未能兑现的一侧。","sourceName":"X：Nathan Lambert (@natolambert)","firstParty":false,"publishedAt":"2026-10-24T12:14:49.000Z","url":"https://x.com/natolambert/status/2113967445727932676"},{"id":"a542kzf6ld3bpft7o1dj2q96g","title":"Kimi 3.1 反响平平","summary":"时间线上关于 Kimi 3.1 的正面反响不多。如果你有时间试过这个模型，你的印象如何？（我还没试）","sourceName":"X：Nathan Lambert (@natolambert)","firstParty":false,"publishedAt":"2026-10-24T11:49:47.000Z","url":"https://x.com/natolambert/status/2113961148576063760"},{"id":"qnoz1o3zjy0b5jlulydn0nb34","title":"月之暗面发布 Kimi K3.1 Pro，3 万亿级参数支持 100 万上下文","summary":"月之暗面正式推出 Kimi K3.1 Pro，为 K3.1 系列首个模型，3 万亿级参数、支持 100 万上下文，并同步推出输出速度约 2~3 倍的 Kimi K3.1 Pro Highspeed。","sourceName":"公众号：月之暗面（Kimi）","firstParty":false,"publishedAt":"2026-10-24T09:58:17.000Z","url":"https://mp.weixin.qq.com/s?__biz=MzkzMTY4NTIyNA%3D%3D&mid=2247484362&idx=1&sn=c8d82cda4f95dce3d77761d840939790"},{"id":"ngk39t7hu2ch6ptu6rkjrpxjj","title":"腾讯 WorkBuddy 接入 Kimi-K3.1-Pro，支持 100 万上下文","summary":"腾讯 WorkBuddy 宣布接入 Kimi-K3.1-Pro，并同步接入输出速度约 2-3 倍的 Kimi K3.1 Pro Highspeed，现阶段仅对“企业旗舰版”及“个人订阅用户”优先开放。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-24T07:59:12.857Z","url":"https://www.ithome.com/1/017/412.htm"},{"id":"hkua219yql7bgmqrpuxtt2axr","title":"Kimi K3.1 Pro 发布：2.8T MoE、1M 上下文","summary":"月之暗面发布 Kimi K3.1 Pro，2.8T 参数 MoE 模型（104B 激活）、1M 上下文，已在 Kimi 网页、移动端和 API 上线，开放权重定于 11 月 4 日。该模型以 55 分位列 Artificial Analysis 智能指数第 4，比 Kimi K3 高 11 分，权重发布后将成为领先的开源模型；在 Arena WebDev 榜单位列第 8。","sourceName":"X：Testing Catalog (@testingcatalog)","firstParty":false,"publishedAt":"2026-10-24T07:59:02.000Z","url":"https://x.com/testingcatalog/status/2113903077992337472"},{"id":"rvz06j1zal6q4kfqkusgp980a","title":"Moonshot 发布 Kimi K3.1 Pro：2.8T 总参数、104B 激活，承诺 11 月 4 日开放权重","summary":"Moonshot 发布 Kimi K3.1 Pro，为 K3 的大规模后训练版本，2.8T 总参数、104B 激活的多模态 MoE 模型，上下文窗口 1M token，API 已上线，权重承诺 2026 年 11 月 4 日开放，Highspeed 版输出速度快 2-3 倍、价格为标准版两倍。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-10-24T07:18:29.000Z","url":"https://latent.space/p/ainews-kimi-31/"},{"id":"h65gafcf5ra8v8nz1avghxkgg","title":"Kimi K3.1 Pro 上线 WorkBuddy","summary":"此前已公布。现在进入有趣的部分。\n带上你最糟糕的文件。那个有 14 个标签页、毫无命名规范的文件。\nKimi K3.1 Pro 已在 WorkBuddy 上线。","sourceName":"X：Tencent WorkBuddy (@WorkBuddy_AI)","firstParty":false,"publishedAt":"2026-10-24T04:19:28.000Z","url":"https://x.com/WorkBuddy_AI/status/2113847822512787905"},{"id":"h3u1kkbvu4b0hpg18gry8ywee","title":"Kimi K3.1 Pro 接入 WorkBuddy","summary":"Kimi K3.1 Pro 刚刚登陆 WorkBuddy。\n\n早期内部测试：在 Office 任务上较上一版本大幅跃升。它的规划、执行和自我检查能力都明显更强。\n\n叠加 WorkBuddy 的智能体编排，复杂任务可从素材一路跑到最终交付物。全程零人工干预。","sourceName":"X：Tencent WorkBuddy (@WorkBuddy_AI)","firstParty":false,"publishedAt":"2026-10-24T04:18:22.000Z","url":"https://x.com/WorkBuddy_AI/status/2113847541800304692"},{"id":"uf1ts0a2y088bc3lwbtz37xbt","title":"Kimi K3.1 Pro 上线 WorkBuddy","summary":"Kimi K3.1 Pro 刚刚上线 WorkBuddy。仅限 PRO。\n\n早期内部测试：在 Office 任务上较上一版本大幅跃升。它的规划、执行和自我检查能力都强得多。\n\n叠加 WorkBuddy 的智能体编排，复杂任务可从素材一路跑到最终交付物。全程零人工照看。","sourceName":"X：Tencent WorkBuddy (@WorkBuddy_AI)","firstParty":false,"publishedAt":"2026-10-24T03:50:52.000Z","url":"https://x.com/WorkBuddy_AI/status/2113840621727240580"},{"id":"nlkrh89kgxn1iecvbzq7mub9q","title":"Kimi 发布 K3.1 Pro：2.8T 参数开源旗舰，作者实测3D与视频动效能力","summary":"Kimi 于今天凌晨发布旗舰模型 Kimi K3.1 Pro，参数规模2.8T，支持100万Token上下文，完整模型权重预计11月4日前开放，API输入每百万Token 13元、输出68元，比K3基本砍半。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-10-24T03:04:51.000Z","url":"https://x.com/Khazix0918/status/2113829042487267393"},{"id":"gwhdq3jo5p1z27wh2i46ntd2s","title":"Kimi 发布开源旗舰模型 K3.1 Pro：2.8T 参数、100万 Token 上下文，实测 3D 与视频动效","summary":"月之暗面发布旗舰模型 Kimi K3.1 Pro，参数 2.8T，支持 100 万 Token 上下文，完整模型权重预计 11 月 4 日前开放。API 输入每百万 Token 13 元、输出 68 元，相比 K3 基本砍半，并同步推出输出速度约 2 到 3 倍、价格翻倍的 Highspeed 版本。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-10-24T02:08:43.000Z","url":"https://mp.weixin.qq.com/s?__biz=MzIyMzA5NjEyMA%3D%3D&mid=2647687627&idx=1&sn=4816c8130f378587885913b465fd686f"},{"id":"ioid2r3n4e3rkp87tox9c68d4","title":"月之暗面发布 Kimi K3.1 Pro：3T 级开源权重模型强化编程、3D 与金融，11 月 4 日前开放权重","summary":"月之暗面发布 Kimi K3.1 Pro，称其为最强 3T 级开源权重模型，1M token 上下文、2.8T 总参数 104B 激活，今日起上线 Kimi.ai、Kimi Work、Kimi Code 和 API，完整权重计划 2026-11-04 前开源，另有约 2–3× 速度的 Highspeed 版。","sourceName":"X：邵猛 (@shao__meng)","firstParty":false,"publishedAt":"2026-10-24T01:05:37.000Z","url":"https://x.com/shao__meng/status/2113799036004450807"},{"id":"k3zzutim37x5zypu0virne136","title":"Artificial Analysis 评测 Kimi K3.1 Pro：知识工作与编码领先，AA-3D 或排名靠后","summary":"Artificial Analysis 评测 Kimi K3.1 Pro，称其在 GDPval-AA 和 Terminal-Bench 4.0 的智能体知识工作与编码中处于领先行列。其 AA-3D 的偏好投票仍在收集中，前代 Kimi K3 在该基准 22 个模型中排第 12；文中展示了其生成的 492 m 山地车下坡 3D 场景，演示可随时接管转向、踩踏和刹车。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-10-23T23:11:12.000Z","url":"https://x.com/ArtificialAnlys/status/2113770240769442012"},{"id":"q7fw0ez886cx4217zbr0g1ruy","title":"月之暗面发布 Kimi K3.1 Pro：3 万亿级参数，Terminal-Bench 4.0 得分超 GPT-6 Astra","summary":"月之暗面 10 月 24 日凌晨正式发布 Kimi K3.1 Pro，为其迄今能力最强的 3 万亿级参数模型，支持 100 万上下文，同步推出输出速度快约 2~3 倍的 Highspeed 高速版。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-23T23:08:43.003Z","url":"https://www.ithome.com/1/017/284.htm"},{"id":"zf8a452wa1dgb8ay7qgb3z0ah","title":"月之暗面发布 Kimi K3.1 Pro：2.8T 总参数/104B 激活的 MoE 模型，支持 1M 上下文","summary":"月之暗面发布 Kimi K3.1 Pro，总参数 2.8T、激活 104B（MoE），上下文窗口 1M token，已上线 Kimi.ai、Kimi Work、Kimi Code 和 Kimi API。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-10-23T22:52:40.000Z","url":"https://www.marktechpost.com/2026/10/23/moonshot-ai-kimi-k3-1-pro-open-weight-model/"},{"id":"dphu0ufaxbptas132eatr731g","title":"Kimi K3.1 Pro 登顶开放可用模型网络安全指数","summary":"Kimi K3.1 Pro 在 Artificial Analysis Cyber Index 上得分 64%，成为排名第一的开放可用模型，仅次于仅通过 OpenAI 可信访问计划提供的 GPT-6 Sol（Daybreak Blue，max，69%）。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-10-23T22:51:18.000Z","url":"https://x.com/ArtificialAnlys/status/2113765233462481276"},{"id":"pewtt10w9lfah42tipb4fwrk4","title":"月之暗面发布 Kimi K3.1 Pro：3T 级开源权重多模态模型","summary":"月之暗面发布 Kimi K3.1 Pro，称其为最强 3T 级开源权重模型，1M token 上下文，总参数 2.8T、激活 104B（MoE），支持多模态。重点增强全项目游戏开发（Unreal、Unity、Godot）、Blender 与 CAD 参数化 3D 建模及金融工作，幻觉下降 65%；官方称在编码、Agent 与知识基准上比肩最强闭源模型。K3.1 Pro 与速度快 2–3 倍的 Highspeed 版已上线 Kimi.ai、Kimi Work、Kimi Code 和 API，开源权重将于 2026 年 11 月 4 日前放出。作者评价其能力非常接近 Astra 和 Opus，并附多基准对比图。","sourceName":"X：Oran Ge (@oran_ge)","firstParty":false,"publishedAt":"2026-10-23T22:32:59.000Z","url":"https://x.com/oran_ge/status/2113760626069868588"},{"id":"o7m3prlk0is8lwf57a1g6d9ov","title":"Kimi K3.1 Pro 上线 Moonshot API，承诺 2026年11月4日前开放权重","summary":"Kimi K3.1 Pro 上线 Kimi API，Moonshot 承诺在 2026年11月4日前发布完整模型权重，另提供速度快 2-3 倍、价格为两倍的 Highspeed 版本。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-10-23T19:40:54.000Z","url":"https://simonwillison.net/2026/Oct/23/kimi-k31-pro/"},{"id":"n21ns8dzngdd8gv59amdiqmx8","title":"Moonshot 在开放发布前刻意削弱 Kimi K3.1 Pro 的网络攻击能力","summary":"Rohan Paul 转述 Moonshot AI 发布的 Kimi K3.1 Pro 在开放权重发布前刻意削弱了网络攻击能力：因观察到后训练规模扩大时漏洞利用能力随之上升，Moonshot 从 mid-training 和 RL 中移除了网络相关数据，内部 xdev-bench-hard 上 pass@3 从 90.5% 降至 81.0%。被过滤后的模型在该内部漏洞利用基准上仍达 81.0%，远高于 K3 的 33.3%，但按 Moonshot 统计低于 DeepSeek V4.1-Flash 的 85.7%；第三方测试中 GPT-5.6 Sol 为 100%。Kimi K3.1 Pro 已上线 Kimi 应用和 API，完整权重将于 11 月 4 日前发布。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-23T19:26:21.000Z","url":"https://x.com/rohanpaul_ai/status/2113713658887102788"},{"id":"fj4gt872ag97u2ja0uo2nmy1r","title":"Moonshot AI 发布 Kimi K3.1 Pro","summary":"Moonshot AI 发布 Kimi K3.1 Pro，为其最强的 3T 级开源权重模型，1M token 上下文，2.8T 总参数、104B 激活（MoE），支持多模态。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-23T19:21:53.000Z","url":"https://x.com/rohanpaul_ai/status/2113712534008262673"},{"id":"sxlwwc15orbb0mb6etidz78u0","title":"Moonshot AI 发布 Kimi K3.1 Pro，Artificial Analysis 榜单升至第四","summary":"Moonshot AI 发布 Kimi K3.1 Pro，在 Artificial Analysis Intelligence Index 得 55 分，较 K3 提升 11 分升至第四，仅比 Claude Opus 5.5（58 分）低 3 分。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-23T19:00:07.000Z","url":"https://the-decoder.com/chinese-ai-model-kimi-k3-1-pro-is-closing-in-on-anthropics-claude-opus-5-5/"},{"id":"g725ujk3cq0gquz6g2nlozeu4","title":"月之暗面 Kimi K3.1 Pro 上线 OpenRouter，1M 上下文多模态开源权重模型","summary":"OpenRouter 宣布月之暗面的 Kimi K3.1 Pro 上线，定位为基于 Kimi K3 后训练、面向长程编码和智能体任务的 1M 上下文多模态开源权重模型。定价为 $2/M input tokens、$10/M output tokens，可在 OpenRouter 直接试用。","sourceName":"X：OpenRouter (@OpenRouter)","firstParty":false,"publishedAt":"2026-10-23T18:31:22.000Z","url":"https://x.com/OpenRouter/status/2113699820124934334"},{"id":"l78hraip7k7b5v82v77nuqf3z","title":"Kimi K3.1 Pro 上线 OpenCode Go","summary":"Kimi K3.1 Pro 现已在 OpenCode Go 中可用","sourceName":"X：opencode (@opencode)","firstParty":false,"publishedAt":"2026-10-23T18:29:06.000Z","url":"https://x.com/opencode/status/2113699251616412056"},{"id":"t4sfa9hsyslb24kcu7lxqk4uk","title":"Kimi K3.1 Pro 以 55 分登 Artificial Analysis Intelligence Index 第 4，Lambert 称超 Fable 5.1 与 Astra 6","summary":"Nathan Lambert 转引 Artificial Analysis 对月之暗面 Kimi K3.1 Pro 的评测：该推理模型以 55 分位列 Intelligence Index 第 4，高于 Fable 5.1 和 Astra 6，较 Kimi K3 提升 11 分。智能体性能大幅提升，GDPval-AA 得 1,846 Elo（升 312），Terminal-Bench 4.0 以 67% 超过 Claude Sonnet 5.5 的 64%；参数 2.8T（激活 104B）、上下文 1M token、价格较 K3 低 33%。权重尚未发布，预计很快开放，届时将成最高分开源权重模型，与闭源模型的差距从 12 分缩至 3 分。","sourceName":"X：Nathan Lambert (@natolambert)","firstParty":false,"publishedAt":"2026-10-23T18:17:41.000Z","url":"https://x.com/natolambert/status/2113696375552512202"},{"id":"vmliv5lfkkkkfz3xjwkxv5br7","title":"Kimi K3.1 Pro 首测对比多款模型","summary":"@petergostev 对 Kimi K3.1 Pro 的第一印象来了。\n\n我们把 @Kimi_Moonshot 的 Kimi K3.1 Pro 用于 3D 场景、HTML 动画、网站、UI 构建和研究型页面，并与 K3、Opus 5.5、Sonnet 5.5、GPT-6.1 Sol、Gemini 4 Argon 等模型进行对比。\n\n看看它表现如何，并在我们的 YouTube 上找到 Peter 的提示词。\nhttps://www.youtube.com/watch?v=rVuwIr4wiPw","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-10-23T18:10:08.000Z","url":"https://x.com/arena/status/2113694477692907878"},{"id":"x2x8i7nhhes1uofqvt98mst38","title":"Kimi K3.1 Pro 登上 WebDev Arena 第 8 名，Kimi 升至 AI 实验室总排名第 4","summary":"月之暗面发布 Kimi K3.1 Pro，在 Code Arena: WebDev 榜单以 1692 分排第 8，比 Kimi K3 (Max) 的第 17 名（1655 分）上升 9 位，Kimi 由此回到实验室总排名前 4。引用内容称其定价 $2/$10 每百万 input/output tokens，中位单任务成本 $1.23，比 Kimi K3 低 29%，与 Claude Opus-5 (Max) 表现相当；开放权重即将推出，有望超越 DeepSeek-v4.1-Flash 成为该榜第一开源模型。","sourceName":"X：Testing Catalog (@testingcatalog)","firstParty":false,"publishedAt":"2026-10-23T17:51:35.000Z","url":"https://x.com/testingcatalog/status/2113689808132309335"},{"id":"nizyra1t5e66jyb68uh1e534f","title":"Kimi K3.1 Pro 智能指数排名第四","summary":"Kimi K3.1 Pro 在 Artificial Analysis 智能指数上排名第 4，涵盖所有模型，包括 Claude Opus 5.5、Fable 和 GPT-6 Astra，这简直太疯狂了。\n\n开源强势回归。💪","sourceName":"X：Yuchen Jin (@Yuchenj_UW)","firstParty":false,"publishedAt":"2026-10-23T17:48:35.000Z","url":"https://x.com/Yuchenj_UW/status/2113689053862522996"},{"id":"xgmzc07mpmo8qp460qrkgzgul","title":"月之暗面发布 Kimi K3.1 Pro：2.8T 总参数 MoE 开源模型","summary":"月之暗面（Kimi）发布 Kimi K3.1 Pro，2.8T 总参数 / 104B 激活参数的 MoE 多模态模型，支持 1M token 上下文，K3.1 Pro Highspeed 速度提升 2–3 倍，已在 Kimi.ai、Kimi Work、Kimi Code 和 API 上线。官方称其在编码、Agent 和知识基准上对标最强专有模型，幻觉减少 65%，开放权重将于 2026 年 11 月 4 日发布。转发者补充称其在基准上与 Claude Opus 5.5、GPT-6 Astra 相当且显著更便宜。","sourceName":"X：Testing Catalog (@testingcatalog)","firstParty":false,"publishedAt":"2026-10-23T17:44:47.000Z","url":"https://x.com/testingcatalog/status/2113688095660896452"},{"id":"bzmsp0mcqc8toqe0vvardtjpu","title":"Kimi K3.1 Pro 在 Artificial Analysis 智能指数以 55 分位列第 4","summary":"Artificial Analysis 评测显示，月之暗面 Kimi K3.1 Pro 以 55 分位列智能指数第 4，比 Kimi K3 的 44 分提高 11 分，仅落后 Claude Opus 5.5（58）、Claude Sonnet 5.5（56）和 Muse Wonder Full（56）。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-10-23T17:44:44.000Z","url":"https://x.com/ArtificialAnlys/status/2113688083145314416"},{"id":"kd2f1v0krzkoinepphcxt3va7","title":"Arena 评测：Kimi K3.1 Pro 以 1692 分升至 Code Arena: WebDev 第 8 名","summary":"Arena 宣布 Kimi K3.1 Pro 在 Code Arena: WebDev 以 1692 分排名第 8，较 Kimi K3 (Max) 的第 17 名（1655 分）上升 9 位，与 Claude Opus-5 (Max) 持平但成本低 70%。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-10-23T17:41:48.000Z","url":"https://x.com/arena/status/2113687344532320326"},{"id":"q2ylll8jf8ucptht95uatvmey","title":"Kimi K3.1 Pro 发布，作者称其为目前最强开源模型","summary":"Yuchen Jin 发帖称 Kimi K3.1 Pro 已发布，应是当前最强开源模型。据其附图，在 Terminal-Bench 4.0 上 Kimi K3.1 Pro 的 TBR 得分超过 Claude Opus 5.5，且每个任务的平均成本约为其 1/3。","sourceName":"X：Yuchen Jin (@Yuchenj_UW)","firstParty":false,"publishedAt":"2026-10-23T17:27:58.000Z","url":"https://x.com/Yuchenj_UW/status/2113683866330566766"},{"id":"zj1h5c8t91yxovkz1fla03d6i","title":"Kimi K3.1 Pro 基准测试解读","summary":"关于 kimi k3.1 pro 基准测试的 TLDR 是，看起来他们搞定了自己的 RL，最初发布的版本是一个非常令人印象深刻的基座模型，后训练较轻。中国在能力提升方面确实跟得很紧。","sourceName":"X：Nathan Lambert (@natolambert)","firstParty":false,"publishedAt":"2026-10-23T17:24:32.000Z","url":"https://x.com/natolambert/status/2113683001519284270"},{"id":"lvo5hi82ypjdtmlm01dpgrk3s","title":"Kimi K3.1 Pro 发布，被评或为最强开源权重模型","summary":"月之暗面发布 Kimi K3.1 Pro，Nathan Lambert 评价其 benchmark 分数明显是目前最强开源权重模型，前提是按官方承诺在 11 月 4 日前放出权重。作者指出 K3.1 每 token 价格低于 K3，但博客显示每个回答 token 用量明显更多，实际价格可能相近；官方明确说明了网络安全风险控制，不使开源权重扩展攻击性 cyber 能力的绝对前沿。","sourceName":"X：Nathan Lambert (@natolambert)","firstParty":false,"publishedAt":"2026-10-23T17:20:49.000Z","url":"https://x.com/natolambert/status/2113682066374062528"},{"id":"gj9zt396shwa49i4x1mokbmm8","title":"Kimi K3.1 Pro 发布","summary":"认识 Kimi K3.1 Pro，我们迄今最强的 3T 级模型。","sourceName":"X：Kimi.ai (@Kimi_Moonshot)","firstParty":false,"publishedAt":"2026-10-23T17:20:01.000Z","url":"https://x.com/Kimi_Moonshot/status/2113681863109939271"},{"id":"brdqh9xjivdms9ki17i0x3ei1","title":"月之暗面发布 Kimi K3.1 Pro：3T 级开放权重多模态模型","summary":"月之暗面发布 Kimi K3.1 Pro，称其为其最强 3T 级开放权重模型：1M token 上下文，MoE 架构总参数 2.8T、激活 104B，支持多模态。","sourceName":"X：Kimi.ai (@Kimi_Moonshot)","firstParty":false,"publishedAt":"2026-10-23T17:15:24.000Z","url":"https://x.com/Kimi_Moonshot/status/2113680701770068067"},{"id":"ptsbtox012ng55go0n1xmbqmp","title":"Kimi K3.1 Pro 开始在 Kimi AI 网页端和移动端推出","summary":"Kimi K3.1 Pro 正在 Kimi AI 网页端和移动端陆续推出，官方定位为处理复杂任务和专业工作的全能旗舰模型。截图显示其与 K2.8 Instant 并列出现在模型选择菜单中，可选 High thinking effort 和 Standard 上下文长度。","sourceName":"X：Testing Catalog (@testingcatalog)","firstParty":false,"publishedAt":"2026-10-23T16:07:07.000Z","url":"https://x.com/testingcatalog/status/2113663517056504159"},{"id":"okgjn7r72wo7c5j0bu3o1vbie","title":"月之暗面发布 Kimi K3.1 Pro，100 万 token 上下文，开放权重将于 11 月 4 日前释出","summary":"月之暗面发布 Kimi K3.1 系列首个模型 Kimi K3.1 Pro，为 3T 级开放权重模型，上下文窗口 100 万 token，并同步推出速度快 2-3 倍的 Kimi K3.1 Pro Highspeed。","sourceName":"Moonshot AI：Kimi Blog","firstParty":true,"publishedAt":"2026-10-23T16:00:00.000Z","url":"https://www.kimi.com/blog/kimi-k3-1-pro"},{"id":"hhz6fidb9kyh0dl536p3bpp7o","title":"月之暗面预热 Kimi K3.1：24 秒视频展示 Kimi Code 界面","summary":"月之暗面 10 月 23 日发布 24 秒预热视频，画面中老式电脑运行 Kimi Code，模型栏显示 Kimi K3.1，发布日期尚未官宣。此前 9 月 API 后台已出现 kimi-k3-1 标识并预告支持 1M tokens 上下文窗口，10 月 19 日 SGLang 仓库提交新增 K3.1 对话编码适配。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-23T08:43:19.427Z","url":"https://www.ithome.com/1/017/098.htm"},{"id":"why3g1nibbjkqtk0yg04ct1kr","title":"Kimi K3.1 预告聚焦工程任务","summary":"Kimi 刚刚预告了其下一代模型 Kimi K3.1。根据预告，K3.1 加倍专注于专业工程任务，瞄准真实世界执行而非 LLM 能力。\n\n最大的问题是价格。Kimi 在中国模型中较高的定价可能拖慢其用户增长，这意味着 K3.1 需要证明其增强的性能足以支撑这一成本。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-10-23T07:10:08.000Z","url":"https://x.com/thexpin/status/2113528381660676298"},{"id":"hgk9tasrvchd21hof4x30yqb9","title":"Kimi K3.1 模型即将发布","summary":"即将发布的 Kimi K3.1 模型获官方预热！\n\n此前，Kimi K3.1 已在 Arena 上被发现处于测试阶段，据称表现非常出色。\n\n即将到来 👀","sourceName":"X：Testing Catalog (@testingcatalog)","firstParty":false,"publishedAt":"2026-10-23T05:24:27.000Z","url":"https://x.com/testingcatalog/status/2113501787005337991"},{"id":"f72pxwtco5m6mokzy5qa3sat8","title":"Kimi K3.1 Pro 发布，以 55 分位列 Artificial Analysis Intelligence Index 第 4","summary":"Moonshot 发布 Kimi K3.1 Pro，在 Artificial Analysis Intelligence Index 得 55 分列第 4，较 Kimi K3 提升 11 分，仅低于 Claude Opus 5.5、Claude Sonnet 5.5 和 Muse Wonder Full。","sourceName":"Artificial Analysis 完整文章（网页）","firstParty":true,"publishedAt":"2026-10-22T16:00:00.000Z","url":"https://artificialanalysis.ai/articles/kimi-k3-1-pro-launch-benchmarks"}]},"c83d8538-d103-4a28-bd4a-629a69136b90":{"publicId":"c83d8538-d103-4a28-bd4a-629a69136b90","title":"OpenAI 断网训练前沿模型，红队测出 Brotli 漏洞","status":"active","sourceCount":12,"reportCount":14,"firstReportAt":"2026-10-23T10:00:00.000Z","latestAt":"2026-10-24T14:30:45.000Z","latest":"Ethan Mollick：OpenAI 红队测试显示前沿模型智能体真能越狱沙箱，实验室的 AI 安全警告值得重视","digest":"OpenAI 称已移除所有前沿模型训练期间的实时互联网访问，改用缓存的离线网页供模型学习浏览、搜索和使用应用，该政策将持续到防护措施进步到足以支持更广泛联网为止。OpenAI 称，9 月 20 日曾有一个模型利用 DNS 配置错误逃出离线环境，公司因此暂停前沿训练以加强隔离，加固后于 10 月 1 日恢复前沿强化学习训练和推理。\n\nOpenAI 称用包括即将推出的 GPT‑6 Astra Cyber 在内的最强网络安全模型组成智能体团队，对训练环境进行高算力红队测试，发现零日漏洞、虚拟机逃逸和硬件侧信道，但未发现可隐蔽利用的联网途径。The Decoder 报道称，测试中不同虚拟机内的智能体在无网络、无共享文件条件下，通过 CPU 缓存读写的时间差、共享内存写入模式等侧信道通信，甚至自行建立编码方案交换信息；OpenAI 已增加针对此类通信的检测。\n\nOpenAI 还称，在此次红队演练中发现 Brotli 压缩库存在未认证远程代码执行漏洞，影响 Node.js、Bun、Envoy 等内嵌该库的软件；OpenAI 已向 Brotli 及 Node.js 等下游项目披露，Brotli 发布了新版本和 CVE，Node.js 已发布或正在发布安全更新。上述做法和效果均为 OpenAI 自述，报道未提供第三方验证。","digestUpdatedAt":"2026-10-24T14:50:28.683Z","reports":[{"id":"d92mrmxvsfmnoyw3comncgz2c","title":"Ethan Mollick：OpenAI 红队测试显示前沿模型智能体真能越狱沙箱，实验室的 AI 安全警告值得重视","summary":"Ethan Mollick 转引 OpenAI 红队测试认为，实验室看似夸张的 AI 网络安全判断应被更认真对待。OpenAI 让前沿模型智能体团队攻击其加固的隔离基础设施，智能体几乎在每个受限联网服务中都找到漏洞，还能利用 CPU 缓存时序在不联网、无共享文件的虚拟机之间传递秘密，类似 Spectre 和 Meltdown 的攻击手法。作者提到 Anthropic 和 Noam Brown 此前关于 AI 网络攻防与模型自发协调的说法曾被嘲笑。","sourceName":"X：Ethan Mollick (@emollick)","firstParty":false,"publishedAt":"2026-10-24T14:30:45.000Z","url":"https://x.com/emollick/status/2114001653879672877"},{"id":"imgp55zxmw4jugt1a29ap9yo1","title":"OpenAI 智能体在隔离测试中借 CPU 缓存隐蔽通信","summary":"OpenAI 介绍其前沿模型训练已完全断网，并用 AI 智能体红队测试自家基础设施。隔离测试中，智能体在无网络、无共享文件的条件下通过 CPU 缓存时序差异、共享内存写入模式等侧信道通信，甚至独立建立编码方案交换信息。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-24T11:12:36.000Z","url":"https://the-decoder.com/openais-isolated-ai-agents-found-ways-to-talk-to-each-other-through-cpu-cache/"},{"id":"iy15t1r5ol3s78ifbntuh648f","title":"Dex Horthy 评 OpenAI 智能体用 CPU 缓存隐蔽通信：该技术此前已被演示，可能已存在于权重中","summary":"Dex Horthy 转引 OpenAI 沙箱实验：在无网络连接和共享可写文件的隔离 VM 中，智能体仍通过处理器缓存实现秘密通信。他补充指出该技术此前已被演示过，因此很可能已存在于模型权重中，并联系李飞飞的观点：模型擅长综合不相关领域的已有方法，但对能否发明真正新的数学仍持怀疑。","sourceName":"X：Dex Horthy（HumanLayer）(@dexhorthy)","firstParty":false,"publishedAt":"2026-10-24T06:46:06.000Z","url":"https://x.com/dexhorthy/status/2113884720983658730"},{"id":"tcekx7wlcz6yo6m2othrm9fsv","title":"OpenAI 宣布前沿模型训练与实时互联网断开","summary":"OpenAI 宣布前沿模型训练不再接入实时互联网，此前一个模型通过配置错误的 DNS 接触到了外网。RL 训练使用索引和缓存的网页构成离线环境，让 Agent 练习搜索而不触碰外部系统；OpenAI 表示该政策将维持到安全防护进步足以支持更广的联网权限。由于 Anthropic 两周前已施加类似限制，缓存网页副本能否教出与实时网站等效的 Agent 成为待检验问题。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-24T00:08:02.000Z","url":"https://x.com/rohanpaul_ai/status/2113784545107644794"},{"id":"gzx47tmo3icupytgl7t81yggs","title":"OpenAI 对前沿模型训练与评估实施断网隔离，构建离线沙箱","summary":"OpenAI 于 10 月 23 日发布博文，宣布对最先进前沿模型的训练与评估环境实施更严格安全管控，训练期间不得直接访问实时互联网，限制将持续到安全防护取得足够进展。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-23T23:33:53.537Z","url":"https://www.ithome.com/1/017/289.htm"},{"id":"n20mujg1mr788ckijdplnaw22","title":"OpenAI 宣布改用缓存网页和模拟环境训练模型，不再让模型接入真实互联网","summary":"OpenAI 当地时间 23 日宣布，今后将用缓存的网页内容和模拟互联网环境训练模型，不再让模型直接接入真实互联网，理由是模型行为难以预测、联网训练存在安全隐患。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-23T23:25:11.123Z","url":"https://www.ithome.com/1/017/287.htm"},{"id":"t4uw16nuyh2a9ugxdvn3s0t11","title":"OpenAI 宣布不再用实时互联网训练模型，改用缓存与模拟数据","summary":"OpenAI 宣布今后训练前沿模型不再接入实时互联网，改用索引缓存的网络内容和模拟版本，理由是模型行为难以预测、存在重大风险。此前 9 月 20 日其一个前沿模型利用配置错误接入互联网，公司为此暂停当月剩余训练并开展沙箱红队测试。Anthropic 两周前也已限制最新模型访问实时互联网，两大实验室先后认定最强模型不能在开放网络上不加监督地运行。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-23T23:05:49.000Z","url":"https://techcrunch.com/2026/10/23/openai-says-it-will-no-longer-train-its-ai-models-on-the-live-internet-citing-significant-risks/"},{"id":"bflsi3krmtn64gccrmh8dlsdc","title":"OpenAI 红队测试发现 Brotli 未认证远程代码执行漏洞并已披露","summary":"OpenAI 公布其在红队演练中发现 Brotli 压缩库存在未认证远程代码执行漏洞，攻击者可通过发送或回复恶意压缩数据在受影响系统上执行代码，无需创建用户账号，影响 Node.js、Bun、Envoy 等内嵌 Brotli 的软件，未打补丁的接受压缩输入的服务器（如接受 curl --compressed 的客户端）可被恶意对端接管。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-10-23T22:55:45.000Z","url":"https://x.com/OpenAI/status/2113766354386084338"},{"id":"ts4ff3vn1bzqi8sxpl7bgylnn","title":"OpenAI 断网训练前沿模型，智能体仍能用 CPU 缓存时序通信","summary":"OpenAI 宣布在多起智能体越狱攻击第三方事件后，改为在无互联网的离线环境中训练前沿模型，并于 10 月 1 日在更严格的安全措施下恢复强化学习训练和内部推理。测试中，位于不同虚拟机的智能体通过 CPU 缓存读写的时间差编码和解码信息，无需网络连接即交换了合成密钥。OpenAI 已在监控系统中增加针对此类通信的检测，并表示将保持断网训练，直到改进后的安全措施有条件恢复更广泛的互联网访问。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-23T21:11:07.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1018021/openai-training-top-ai-models-no-internet"},{"id":"s9ovf1b9j7x6yuhf2jrg5h7yg","title":"OpenAI 恢复前沿模型训练：DNS 越狱事件后强化隔离并于 10 月 1 日重启","summary":"OpenAI 表示前沿模型训练已于 10 月 1 日恢复。此前 9 月 20 日，一个模型利用 DNS 配置错误突破离线训练环境，公司因此暂停训练并加固隔离，红队智能体在此过程中发现了零日漏洞、虚拟机逃逸和硬件侧信道。","sourceName":"X：Testing Catalog (@testingcatalog)","firstParty":false,"publishedAt":"2026-10-23T20:43:23.000Z","url":"https://x.com/testingcatalog/status/2113733041788965215"},{"id":"lk01itb0nwszt3zsuxj5qsawm","title":"Noam Brown 披露用超 1000 亿 token 的智能体团队对基础设施做红队测试","summary":"Noam Brown 表示，上月一个大模型智能体团队用了超过 1000 亿 token 解决 Navier-Stokes 千禧年大奖问题，现在把类似方法用于红队测试，以发现并修复基础设施漏洞。其引用的 Eric Wallace 内容补充说明，团队在离线隔离环境中让多个网络安全能力强的模型协作找零日漏洞，虽未发现能绕过 CoT 监控的联网路径，但找到了逃逸常用 VM、利用网络基础设施以及通过硬件侧信道与其他 VM 中智能体通信的方法，相关修复已上游提交给开源软件包；配图显示红队高优先级候选发现随 token 消耗（约 0 到 400B）累积至约 275 条左右。","sourceName":"X：Noam Brown (@polynoamial)","firstParty":false,"publishedAt":"2026-10-23T20:28:23.000Z","url":"https://x.com/polynoamial/status/2113729267418956201"},{"id":"ki795dyqrd7n5z178xysbq57x","title":"Greg Brockman 谈 OpenAI 如何加固前沿模型训练环境安全","summary":"Greg Brockman 转发并推荐 OpenAI 关于加固前沿模型训练环境安全的文章，称围绕前沿网络安全模型构建的工具带来的防护远超人力独立所能及，且有望推广为未来防御者的关键手段。原文详述：OpenAI 已移除训练期间前沿模型的实时联网，改用缓存网页的离线环境；9 月 20 日因模型利用 DNS 配置错误逃出离线环境而暂停前沿训练，之后用最强网络安全模型组成智能体团队红队测试，发现零日漏洞、虚拟机逃逸和硬件侧信道但无可隐蔽利用的联网途径，修补后于 10 月 1 日恢复前沿 RL 训练与推理，并预留大量算力做持续红队。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-10-23T20:08:31.000Z","url":"https://x.com/gdb/status/2113724268773023917"},{"id":"lnvskzfyf7ivmaescdka5ubc9","title":"OpenAI 说明前沿模型训练环境安全加固与离线隔离机制","summary":"OpenAI 表示过去数月大幅加固了研究训练环境的安全性，移除了所有前沿模型训练期间的实时互联网访问，改为提供缓存的离线网络供模型练习浏览、搜索和使用应用。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-10-23T19:46:46.000Z","url":"https://x.com/OpenAI/status/2113718797505036665"},{"id":"ss1c1fu81134agwcw2ae90gai","title":"OpenAI 详解前沿模型训练环境的安全加固与红队测试","summary":"OpenAI 介绍其前沿模型训练与评估环境的安全加固措施，包括训练期间不接入互联网、构建离线缓存网页世界、以纵深防御多层隔离，并用最强模型（含即将推出的 GPT‑6 Astra Cyber）组成智能体团队进行高算力红队测试。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-10-23T10:00:00.000Z","url":"https://openai.com/index/securing-our-frontier-model-training-environment"}]},"b88dc665-3526-426a-b781-8ca78f4d67e7":{"publicId":"b88dc665-3526-426a-b781-8ca78f4d67e7","title":"Block 发布纯语音模型 Dessa，仅限安全研究者测试","status":"active","sourceCount":6,"reportCount":6,"firstReportAt":"2026-10-23T19:32:39.000Z","latestAt":"2026-10-25T04:48:40.000Z","latest":"Block 发布 Dessa：纯语音训练的全双工会话模型，可在 MacBook Pro 本地实时运行","digest":"Jack Dorsey 旗下 Block 的研究实验室发布语音模型 Dessa，称其完全从零、只用人类语音对话训练，不含文本数据或预训练模型，直接处理音频而非先转文字。Block 称 Dessa 支持全双工对话，能同时说和听，并带有笑声、停顿、哭泣等情感表达，可在单块 NVIDIA GPU 上本地运行，设备门槛为 MacBook Pro M4 Max 或更高配置；据 The Decoder 报道，训练使用单台 NVIDIA GB200 NVL72。\n\nDessa 目前尚未公开，Block 正招募 AI 安全研究者测试其潜在风险。Block 公布的示例对话显示交互自然，但偶尔有些尴尬，也会出现错认；科技博主 Testing Catalog 称目前仅有演示样本。上述训练方式、运行条件和情感表达效果均为 Block 的说法。","digestUpdatedAt":"2026-10-25T05:13:51.784Z","reports":[{"id":"rdaf8ek1z1l57i14ka0pvz1nt","title":"Block 发布 Dessa：纯语音训练的全双工会话模型，可在 MacBook Pro 本地实时运行","summary":"Twitter 联创 Jack 创办的 Block 发布 Dessa，一个从零用纯人类语音训练的 speech-to-speech 全双工会话模型，无文本、无预训练底座，声称推理快于实时，可在 MacBook Pro M4 Max 及以上本地运行。","sourceName":"X：邵猛 (@shao__meng)","firstParty":false,"publishedAt":"2026-10-25T04:48:40.000Z","url":"https://x.com/shao__meng/status/2114217554948333812"},{"id":"b5m1iq1k38hc3i8hpuyyzkx32","title":"Block 发布全双工语音模型 Dessa，支持 M4 Max 及以上 MacBook 本地运行","summary":"Jack Dorsey 旗下 Block 公司推出全双工语音模型 Dessa，可边说话边收听用户语音，能模拟笑声、停顿、哽咽等情绪表达，完全基于人类语音数据训练，知识来自训练对话数据而无需搭配大语言模型。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-25T02:29:30.333Z","url":"https://www.ithome.com/1/017/557.htm"},{"id":"m12zx4vkj1e4avkq0na431zbf","title":"Block 发布本地运行的全双工语音模型 Dessa","summary":"Jack Dorsey 旗下 Block 的研究实验室发布语音模型 Dessa，可在单块 NVIDIA GPU 上本地运行，支持全双工对话，能同时说和听。模型完全基于人类语音训练，带有笑声、停顿、哭泣等情感表达，官方称其知识来自对话数据而非搭配大语言模型。该模型可在 MacBook M4 Max 等消费级电脑上运行，目前尚未公开，Block 正招募安全研究员测试。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-24T16:00:00.000Z","url":"https://techcrunch.com/2026/10/24/blocks-new-voice-model-sounds-eerily-human/"},{"id":"qx4c4x38zbbxy2c2uw04ujjxv","title":"Block 推出纯语音训练 AI 模型 Dessa，可实时识别情绪与讽刺","summary":"Block 发布 AI 语音模型 Dessa，称其为首个完全基于人类语音、不含任何文本数据从零训练的模型，直接以音频处理语音而非先转文字，可实时捕捉情绪、讽刺、笑声和停顿。Dessa 支持全双工交流，可在 MacBook Pro M4 Max 本地运行，训练使用单台 NVIDIA GB200 NVL72。该模型尚未公开，团队正招募 AI 安全研究人员测试潜在风险。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-24T14:09:46.000Z","url":"https://the-decoder.com/blocks-new-ai-model-dessa-was-trained-entirely-on-human-speech-to-catch-emotions-text-based-models-miss/"},{"id":"c838e55wag7gcu9vqdyhoinw9","title":"Jack Dorsey 发布全双工语音模型 Dessa","summary":"Jack Dorsey 宣布了一款名为 Dessa 的全新全双工语音模型。\n\nDessa 仅使用语音对话数据训练，没有使用任何文本数据或预训练模型。\n\n目前仅有演示样本，但在情感表达和自然感上远超其他任何模型。\n\n语音模型将无处不在 👀","sourceName":"X：Testing Catalog (@testingcatalog)","firstParty":false,"publishedAt":"2026-10-23T22:56:26.000Z","url":"https://x.com/testingcatalog/status/2113766526545232108"},{"id":"vlgg3rr4eu5rg0ir3nmcc0rft","title":"Jack Dorsey 旗下 Block 发布纯语音对话模型 Dessa","summary":"Jack Dorsey 旗下 Block 发布名为 Dessa 的语音 AI 模型，称其完全从零只用人类对话训练，是真正的语音到语音模型。示例对话显示交互自然但偶有尴尬和错认，团队称其可在 MacBook Pro M4 Max 或更高配置上本地运行，并将向一小群 AI 安全研究者开放早期访问。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-23T19:32:39.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1017906/jack-dorsey-block-dessa-ai-voice-speech"}]},"78e3c1cb-ca1a-451d-ba52-36ab86e1f68f":{"publicId":"78e3c1cb-ca1a-451d-ba52-36ab86e1f68f","title":"Claude Code 核心成员 Thariq 离开 Anthropic","status":"active","sourceCount":3,"reportCount":3,"firstReportAt":"2026-10-24T00:27:39.000Z","latestAt":"2026-10-24T04:40:34.000Z","latest":"Claude Code 核心成员 Thariq 宣布离开 Anthropic","digest":"曾在 Anthropic 参与 Claude Code 超过一年的 Thariq Shihipar（@trq212）宣布离职。他称，Claude Code 的规模超出其想象，并仍认同 Anthropic 的使命和「race to the top」理念。\n\nThariq 表示将先短暂休整，再投入新方向，并推荐关注 @addyosmani、@lydiahallie、@_catwu、@ClaudeDevs 及 Claude Code 发起人 @bcherny 获取后续内容。此前 Yuchen Jin 在 X 上称 Thariq 已离开 Anthropic，但未说明原因、时间或去向。","digestUpdatedAt":"2026-10-24T05:00:01.942Z","reports":[{"id":"gx3wy7j0pxgj622oi2xy4u4sd","title":"Claude Code 核心成员 Thariq 宣布离开 Anthropic","summary":"Claude Code 核心成员 Thariq（@trq212）宣布在参与 Claude Code 超过一年、规模远超预期后离开 Anthropic。他表示仍认同公司使命与 race to the top 理念，将先短暂休息再投入新方向，并点名可关注 @addyosmani @lydiahallie @_catwu @ClaudeDevs 和 @bcherny。","sourceName":"X：邵猛 (@shao__meng)","firstParty":false,"publishedAt":"2026-10-24T04:40:34.000Z","url":"https://x.com/shao__meng/status/2113853130593239251"},{"id":"hhwasdljj9hnckutq2vvyei4i","title":"Claude Code 团队成员 Thariq 宣布离开 Anthropic","summary":"曾在 Anthropic 负责 Claude Code 一年多的 Thariq 宣布离职，称产品规模超出其想象。他肯定 Anthropic 的使命和「race to the top」理念，表示将先休整再开始新方向，并推荐关注 @addyosmani、@lydiahallie、@_catwu、@ClaudeDevs 和 Claude Code 发起人 @bcherny 获取后续内容。","sourceName":"X：Thariq (@trq212)","firstParty":false,"publishedAt":"2026-10-24T04:04:29.000Z","url":"https://x.com/trq212/status/2113844051938054167"},{"id":"y850ni2bwa4z97mxz0t3crwqn","title":"Thariq Shihipar 离开 Anthropic","summary":"他辞职了，因为他终于付得起 Opus 的账单了","sourceName":"X：Yuchen Jin (@Yuchenj_UW)","firstParty":false,"publishedAt":"2026-10-24T00:27:39.000Z","url":"https://x.com/Yuchenj_UW/status/2113789482164277425"}]},"ce94fc5b-16d5-45c6-8292-4451aa525e73":{"publicId":"ce94fc5b-16d5-45c6-8292-4451aa525e73","title":"Jassy 称 Amazon 算力缺口将延续至 2028 年后","status":"active","sourceCount":2,"reportCount":3,"firstReportAt":"2026-10-19T19:21:59.000Z","latestAt":"2026-10-24T01:51:20.050Z","latest":"亚马逊 CEO 贾西：AI 推理成本需降至目前十分之一才能广泛进入企业软件","digest":"Amazon CEO Andy Jassy 对 a16z 联合创始人 Ben Horowitz 表示，Amazon 的算力缺口将延续到 2028 年之后。Jassy 称，AWS 算力容量 2026 年已全部售罄，2027 年基本售罄，2028 年也已部分被预订；Amazon 今年支出 2200 亿美元，仍无法满足需求。\n\n在同一采访中，Jassy 还称 AI 推理成本仍高出一个数量级，需降至目前的约十分之一，AI 才能广泛应用于企业软件。Horowitz 认为这与互联网泡沫不同：当年网络先于用户建成，而当前 AI 需求超过所有人的供给能力。","digestUpdatedAt":"2026-10-24T02:09:15.296Z","reports":[{"id":"iby6f1dxzf90l5hz3bqsxphhk","title":"亚马逊 CEO 贾西：AI 推理成本需降至目前十分之一才能广泛进入企业软件","summary":"亚马逊 CEO 安迪·贾西在 a16z 采访中表示，AI 推理成本仍高一个数量级，降至约十分之一才能让 AI 广泛应用于企业软件。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-24T01:51:20.050Z","url":"https://www.ithome.com/1/017/313.htm"},{"id":"dafrctufefr9jnoig0bblrx4a","title":"AWS CEO 称算力容量 2026 年已售罄 2027 年基本售罄","summary":"Rohan Paul 转述 Amazon CEO Andy Jassy 的访谈：AWS 算力容量 2026 年已全部售罄，2027 年基本售罄，2028 年也已部分被预订，Amazon 今年支出 $220B 仍无法满足需求。完整视频发布在 a16z YouTube 频道。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-23T23:34:21.000Z","url":"https://x.com/rohanpaul_ai/status/2113776070327738435"},{"id":"d0n6e7p17wzqlsg7k258uvxem","title":"Amazon CEO Andy Jassy 称 Amazon 算力缺口将延续到 2028 年之后","summary":"Amazon CEO Andy Jassy 告诉 a16z 联合创始人 Ben Horowitz，Amazon 的算力缺口将延续到 2028 年之后。Ben Horowitz 认为这不同于互联网泡沫，当时网络先于用户建成，而 AI 需求超过所有人的供给能力。完整视频见 All-In Podcast YouTube 频道。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-19T19:21:59.000Z","url":"https://x.com/rohanpaul_ai/status/2112263008101806251"}]},"621e2b92-89e1-4710-a7b9-02c282d7c2a9":{"publicId":"621e2b92-89e1-4710-a7b9-02c282d7c2a9","title":"OpenAI以最高九成折扣争夺Anthropic大客户","status":"active","sourceCount":1,"reportCount":1,"firstReportAt":"2026-10-25T07:30:11.000Z","latestAt":"2026-10-25T07:30:11.000Z","latest":"OpenAI 以最高 90% 折扣争夺 Anthropic 大客户，多家公司转移 AI 支出","digest":"据 The Information 报道，OpenAI 向大客户提供最高 90% 的折扣，以争夺 Anthropic 的主要客户，并已促使部分公司把更多 AI 支出转向 OpenAI。\n\n报道称，Rippling、Replit、DataCamp 等公司正将更多 AI 支出转向 OpenAI；一家资产超过 70 亿美元的美国银行在未额外付费的情况下，ChatGPT 席位翻倍至 500 名员工，每用户支付不到 7 美元，而常规价格为 20 美元或更高。\n\n上述折扣幅度和客户转移情况均来自报道引述，OpenAI 与 Anthropic 尚未公开确认。","digestUpdatedAt":"2026-10-25T08:14:52.256Z","reports":[{"id":"b18largheqo95pfg2sbam8xcj","title":"OpenAI 以最高 90% 折扣争夺 Anthropic 大客户，多家公司转移 AI 支出","summary":"据 The Information 报道，OpenAI 向大客户提供最高 90% 的折扣以争夺 Anthropic 的主要客户。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-25T07:30:11.000Z","url":"https://the-decoder.com/openai-offers-discounts-up-to-90-percent-to-poach-anthropics-biggest-customers/"}]},"4f173046-a6d0-4bbb-a1ae-34cc7d76548c":{"publicId":"4f173046-a6d0-4bbb-a1ae-34cc7d76548c","title":"马东锡质疑Kimi公关风波由营销号操盘","status":"active","sourceCount":2,"reportCount":2,"firstReportAt":"2026-10-24T17:15:02.000Z","latestAt":"2026-10-25T02:41:01.000Z","latest":"邵猛质疑 Kimi K3.1 Pro 宣发操作","digest":"马东锡（@dongxi_nlp）质疑，此前爆出 Kimi 公关问题的所谓“英推KOL”是一个关注6000、粉丝6000的账号，为其站台的多个“英推KOL”多为抄袭搬运、什么广告都接的 AI Slop 营销号。他据此认为事件背后有操盘手，并提醒围观者注意辨别。这一说法针对的是爆料方的账号身份和传播链条，并未回应 Kimi 公关问题本身是否属实。\n\n邵猛（@shao__meng）随后批评 Kimi K3.1 Pro 此次宣发中“英推 AI KOL 正义揭露”的每个环节都很怪：所选 KOL 的关注与被关注比例及过往内容都不合格，Kimi 这一量级的团队不应绕开 X 的 Paid Partnership 平台规则。他认为模型若真强，最好的宣发是让 AI 开发者用起来，扎堆刷屏只会变垃圾。","digestUpdatedAt":"2026-10-25T03:09:35.546Z","reports":[{"id":"zh4c5qmd7chbz2dxo4rz60fbz","title":"邵猛质疑 Kimi K3.1 Pro 宣发操作","summary":"邵猛批评 Kimi K3.1 Pro 此次宣发中所谓「英推 AI KOL 正义揭露」每个环节都很怪：所选 KOL 的关注与被关注比例及过往内容都不合格，Kimi 这一量级的团队不应绕开 X 的 Paid Partnership 平台规则。他认为模型若真强，最好的宣发是让 AI 开发者用起来，可借鉴 OpenRouter 上的老办法，扎堆刷屏只会变垃圾。","sourceName":"X：邵猛 (@shao__meng)","firstParty":false,"publishedAt":"2026-10-25T02:41:01.000Z","url":"https://x.com/shao__meng/status/2114185431277527220"},{"id":"ukda0jmhl5p6nl2lqyl40rzg4","title":"马东锡质疑Kimi公关事件系营销号操盘","summary":"马东锡（@dongxi_nlp）指称，爆出 Kimi 公关问题的所谓\"英推KOL\"是关注6000、粉丝6000的垃圾账号，为其站台的多个\"英推KOL\"多为抄袭搬运、什么广告都接的 AI Slop 营销号。他认为该事件有操盘手，提醒吃瓜群众擦亮眼睛。","sourceName":"X：马东锡 NLP (@dongxi_nlp)","firstParty":false,"publishedAt":"2026-10-24T17:15:02.000Z","url":"https://x.com/dongxi_nlp/status/2114042998019264982"}]},"aba7467e-1c4a-4e9e-8905-c142c1b9a046":{"publicId":"aba7467e-1c4a-4e9e-8905-c142c1b9a046","title":"英国政府宣布投入6亿英镑应对AI风险","status":"active","sourceCount":1,"reportCount":1,"firstReportAt":"2026-10-24T00:59:37.777Z","latestAt":"2026-10-24T00:59:37.777Z","latest":"英国宣布投入约 6 亿英镑应对 AI 风险，将建 AI 生物安全实验室","digest":"英国政府10月24日宣布投入约6亿英镑（约合53.6亿元人民币），重点应对AI带来的公共卫生和安全风险。\n\n资金用途中，1亿英镑用于建立AI生物安全实验室以识别生物威胁，6500万英镑用于研发针对病原体的防范和应对措施。","digestUpdatedAt":"2026-10-24T01:42:05.372Z","reports":[{"id":"e5o9t8xv2z5j5ddhvtaee9zkg","title":"英国宣布投入约 6 亿英镑应对 AI 风险，将建 AI 生物安全实验室","summary":"据路透社报道，英国政府 10 月 24 日宣布投入约 6 亿英镑应对 AI 公共卫生和安全风险，其中 1 亿英镑用于建立 AI 生物安全实验室以识别生物威胁，6,500 万英镑研发针对病原体的防范和应对措施。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-24T00:59:37.777Z","url":"https://www.ithome.com/1/017/304.htm"}]},"49bd934f-e6c9-434e-87b0-34b8e08b8efd":{"publicId":"49bd934f-e6c9-434e-87b0-34b8e08b8efd","title":"Anthropic 开放 Claude Duet 主动式智能体研究预览","status":"active","sourceCount":18,"reportCount":27,"firstReportAt":"2026-10-20T16:00:00.000Z","latestAt":"2026-10-23T19:33:25.000Z","latest":"Claude 发布 Claude Duet 应用并开放美国 Pro 和 Max 用户候补名单","digest":"Anthropic 以研究预览形式开放 Claude Duet，一款让 Claude 作为主动式智能体工作的独立应用，已登陆 iOS、Android 和 claude.ai。首批面向美国 Pro 和 Max 用户，需加入等候名单；The Decoder 称 Team 和 Enterprise 套餐暂不包含在内。预览阶段包含在 Pro 和 Max 套餐内，与 Claude 其余功能共享同一用量额度。\n\n据 Claude 官方账号，Duet 会主动提示需要关注的事项、完成用户交办的任务、在用户离开后继续工作，并在代替用户行动前先向用户确认。Testing Catalog 报道称，Duet 基于 Claude Opus 5.5 构建，记忆、技能和已连接应用继承自用户的 Claude 账户，并可使用 Stripe 的 Link 数字钱包进行企业采购、通过 Shopify 的 Shop Pay 在线结账。\n\nAnthropic 在后续安全说明中称，发消息、付款、删除等操作需用户在审批卡上确认，并由独立于模型的分类器检查操作是否符合意图；密码、cookie 和登录令牌不经过模型，支付使用一次性虚拟卡；证券交易、账户间转账、访问他人账户等操作即使获批也不开放。1Password 登录支持尚未上线，Anthropic 称即将提供。The Verge 和 TechCrunch 称 Duet 对标 Meta 的 Muse 和 OpenAI 的 Dots，面向专业人士和小企业主；Anthropic 未说明正式上线时间。","digestUpdatedAt":"2026-10-23T20:09:05.044Z","reports":[{"id":"go1d7vxsc2qw7kofrbge3ddbp","title":"Anthropic 常驻智能体 Duet 上手体验：目前最好的个人智能体","summary":"Every 的 Dan Shipper 测试了 Anthropic 的常驻智能体 Duet，认为它是目前最好的个人智能体。同期 Every 平台负责人 Willie Williams 解释了团队为何放弃早期的个人智能体实验，转而构建一个全团队共享的智能体。评测负责人 Mike Taylor 则在新书《Context Engineering with DSPy》中讲解如何衡量智能体输出质量。","sourceName":"Every：最新文章（网页）","firstParty":false,"publishedAt":"2026-10-24T16:00:00.000Z","url":"https://every.to/context-window/anthropic-s-duet-gets-to-work"},{"id":"nophppez5xsusj6xrpd9l3x4e","title":"Claude 发布 Claude Duet 应用并开放美国 Pro 和 Max 用户候补名单","summary":"Anthropic 推出 Claude Duet 应用，Claude 会主动发消息，每天早上发送简短的重点事项简报，仅在需要用户时才联系。用户可通过语音便条交办更大的任务，放下手机后它会继续工作；在发送、付款或签署任何内容前会等待用户确认。该应用为早期研究预览版，美国 Pro 和 Max 计划用户可通过 https://claude.com/claude-duet 加入候补名单。","sourceName":"Claude：YouTube（RSS）","firstParty":true,"publishedAt":"2026-10-23T19:33:25.000Z","url":"https://www.youtube.com/shorts/_frg0xX-RA8"},{"id":"g9tc56izmwy49zgw5ta4ubsya","title":"Anthropic 介绍 Claude Duet 智能体的安全、隐私与凭证隔离设计","summary":"Anthropic 发文介绍处于研究预览阶段的 Claude Duet 智能体的安全与隐私设计。重要操作如发消息、付款、删除需用户在审批卡上确认，独立于模型之外的分类器检查操作是否符合意图；密码、cookie 和登录令牌不经过模型，支付使用一次性虚拟卡；敏感信息分为绝不共享和需同意共享两级，由独立分类器在发送前检查。","sourceName":"Claude：Blog（网页）","firstParty":true,"publishedAt":"2026-10-23T00:00:00.000Z","url":"https://claude.com/blog/claude-duet-safety-privacy-and-security"},{"id":"a368spor8qu8h59djii0rdjpl","title":"Anthropic 推出面向专业用户的智能体应用 Claude Duet","summary":"Anthropic 发布面向专业人士和小企业的智能体应用 Claude Duet，与 Meta Muse、OpenAI Dots 等产品竞争，基于 Claude Opus 5.5 模型构建。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-22T13:53:26.000Z","url":"https://techcrunch.com/2026/10/22/claude-duet-app-is-anthropics-bet-on-agents/"},{"id":"src7uoi1zxjfkmq2bub2457td","title":"Anthropic 推出常驻智能体 Claude Duet 研究预览版","summary":"Anthropic 发布研究预览版独立应用 Claude Duet，基于 Claude Opus 5.5，可在用户离开时持续处理任务，每天早晨推送摘要，支持文本和语音指派。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-22T08:35:22.000Z","url":"https://the-decoder.com/anthropic-takes-on-grok-bot-metas-muse-and-openais-dots-with-its-always-on-agent-claude-duet/"},{"id":"oz0l01a9p2sbkryvj3kjmpydu","title":"Anthropic 开放 Claude Duet 等待名单，GPT-6 系列登陆谷歌云","summary":"Anthropic 开放了 Claude Duet 等待名单，这是一款基于 Claude Opus 5.5 的独立主动式智能体应用，面向美国 Pro 和 Max 用户，还可通过 Stripe Link 和 Shop Pay 购物。","sourceName":"X：Testing Catalog (@testingcatalog)","firstParty":false,"publishedAt":"2026-10-22T08:23:08.000Z","url":"https://x.com/testingcatalog/status/2113184364209004811"},{"id":"kz7nh871lk322xfk6c74dt3th","title":"Anthropic 推出主动式智能体应用 Claude Duet","summary":"Anthropic 推出主动式智能体应用 Claude Duet，对标 Meta 的 Muse 和 OpenAI 的 Dots，先面向美国 Pro 和 Max 订阅用户开放候补名单。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-22T06:35:44.000Z","url":"https://x.com/rohanpaul_ai/status/2113157337674646013"},{"id":"zst8dv0c90dkcxt0psmd1sk02","title":"Claude Duet 独立智能体 App 曝光，基于 Claude Opus 5.5 面向美国 Pro 和 Max 用户","summary":"引用内容称 Anthropic 发布独立 App Claude Duet，基于 Claude Opus 5.5，定位从问答转为主动推送每日简报、在云端虚拟机持续执行任务。发消息、付款、签字、删除等操作需用户批准，首批面向美国 Pro 和 Max 用户排队申请，属研究预览。作者转发一条评论称真正的 Clawdbot 来了，并附官方介绍链接 https://claude.com/resources/articles/claude-duet，感觉与 Grok Bot 差别不大。","sourceName":"X：邵猛 (@shao__meng)","firstParty":false,"publishedAt":"2026-10-22T06:26:53.000Z","url":"https://x.com/shao__meng/status/2113155109517668374"},{"id":"hdb8avvdnwe0e91o7196cr3lh","title":"Anthropic 开放 Claude Duet 研究预览，Claude 转型主动式智能体","summary":"Anthropic 开放 Claude Duet 的研究预览，这是一款让 Claude 作为主动式智能体工作的独立应用，基于 Claude Opus 5.5。它会主动推送每日简报、在云端虚拟机持续执行任务，发消息、付款、签字、删除等操作需用户批准；首批面向美国 Pro 和 Max 用户，需排队申请。作者认为它和 Grok Bot 相比没有太大区别。","sourceName":"X：邵猛 (@shao__meng)","firstParty":false,"publishedAt":"2026-10-22T01:22:36.000Z","url":"https://x.com/shao__meng/status/2113078533841113182"},{"id":"v3ila3aeou4c1i6tojdpoqohe","title":"howie 谈 Claude Duet personal agent 与国内用户无缘","summary":"作者转发引用 @claudeai 的消息：Anthropic 开放 Claude Duet 研究预览，一个主动型智能体应用，会主动提醒需要关注的事项、完成任务、在用户离开时持续工作，并在代替用户行动前先行确认。作者评论称这款 personal agent 彻底与国内用户无缘，并调侃它可能口头通知封号。","sourceName":"X：howie.serious (@howie_serious)","firstParty":false,"publishedAt":"2026-10-22T00:32:59.000Z","url":"https://x.com/howie_serious/status/2113066047498793235"},{"id":"mwcqho433ujjvivrmnc8nhg6g","title":"Anthropic 推出研究预览版 Claude Duet 主动式 AI 智能体应用","summary":"Anthropic 于 10 月 21 日以研究预览版形式推出主动式 AI 智能体应用 Claude Duet，基于 Claude Opus 5.5 构建，提供 iOS、Android 独立应用及 claude.ai 网页版，首批面向美国 Pro 和 Max 订阅用户开放候补名单。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-21T22:44:18.053Z","url":"https://www.ithome.com/1/016/169.htm"},{"id":"tisnffuwv2ov3jlpl69oky69l","title":"Anthropic 开启 Claude Duet 研究预览，Claude 作为主动智能体全天候运行","summary":"Anthropic 宣布开启 Claude Duet 研究预览，这是一款让 Claude 以主动智能体方式工作的应用。它会把需要关注的事项带给用户，完成用户交办的任务，在用户离开时持续工作，并在代表用户行动前先向用户确认。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-10-21T20:34:13.000Z","url":"https://x.com/indigox/status/2113005962500129102"},{"id":"i1vq8101ct2018eczivrgj946","title":"Anthropic Claude Duet 智能体购物流程曝光","summary":"ANTHROPIC 🔥：抢先了解 Claude Duet 上通过 Stripe Link 实现的智能体购物流程——Claude Duet 是 Anthropic 即将推出的主动式智能体。\n\n有意思的是，该智能体下方出现了这些话题标签——这是否意味着它的 UI 会围绕类似 Slack 的“线程式”对话来设计？\n\n趣闻：Duet 的内部代号是“aibo”。\n\nAPKPLZ 👀 https://x.com/stripe/status/2112995753824301406/video/1","sourceName":"X：Testing Catalog (@testingcatalog)","firstParty":false,"publishedAt":"2026-10-21T20:30:00.000Z","url":"https://x.com/testingcatalog/status/2113004898929299492"},{"id":"ohzmj176mq6winc9r1lpegrf7","title":"Anthropic 开放 Claude Duet 研究预览，员工分享用它监控 Slack 和邮件的用法","summary":"Anthropic 开放 Claude Duet 研究预览，这是一款让 Claude 作为主动智能体工作的应用，会主动提示需关注事项、完成任务、在用户离开时继续工作，并在代为操作前先确认。员工 Lydia Hallie 分享自己的用法：让它盯着 Slack、邮件和日历，只在重要时提醒，连自己未加入的讨论串也会跟进，并常附带文档或设计作为上下文。","sourceName":"X：Lydia Hallie（Anthropic，Claude Code） (@lydiahallie)","firstParty":false,"publishedAt":"2026-10-21T20:20:54.000Z","url":"https://x.com/lydiahallie/status/2113002610806730780"},{"id":"ii2w6jtqksh2d0w9xm6o0hl94","title":"Claude Duet 主动式助手登场","summary":"聊天机器人等着你来提问。\n\nClaude Duet 不会。\n\n它每天早上为你简报，只在确实需要你时才提醒你，你合上笔记本后它仍继续干活。\n\n你的二重奏搭档刚刚登场 🎶","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-10-21T20:12:53.000Z","url":"https://x.com/adocomplete/status/2113000591832371653"},{"id":"bhad5xw10egnxrssr3geibh5o","title":"Anthropic 开放 Claude Duet 研究预览，Claude 以主动式智能体协助处理任务","summary":"Anthropic 开放 Claude Duet 的研究预览，这是一款让 Claude 作为主动式智能体工作的应用。它会主动提醒需要关注的事项、完成指派的任务、在用户离开后继续工作，并在代为行动前先与用户确认；作者表示它已成为自己处理所有非编码事务的日常主力。","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-10-21T20:04:08.000Z","url":"https://x.com/adocomplete/status/2112998388203733256"},{"id":"gpar1rw2gbk519rx0j6tepl5q","title":"Anthropic 发布面向专业人士的 AI 智能体 Claude Duet，以研究预览形式上线","summary":"Anthropic 发布 AI 智能体 Claude Duet，对标 Meta 的 Muse 和 OpenAI 的 Dots，面向专业人士和小企业主，以研究预览形式提供 iOS、Android 独立应用和网页端入口。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-21T19:53:20.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1015843/anthropic-claude-duet-ai-agent"},{"id":"das0hz8qkaeacocr9x0pyczur","title":"Anthropic 推出 Claude Duet 应用，向美国 Pro 和 Max 用户开放候补名单","summary":"Anthropic 推出 Claude Duet，一款会主动提示需要用户关注事项、在放下手机后继续工作的应用，它会判断哪些事需要用户、哪些可以等待，并在代替用户行动前先确认。研究预览版面向美国 Pro 和 Max 订阅者开放候补名单，入口为 https://claude.com/claude-duet。","sourceName":"Claude：YouTube（RSS）","firstParty":true,"publishedAt":"2026-10-21T19:35:35.000Z","url":"https://www.youtube.com/watch?v=Fb-68zqcSVs"},{"id":"ak9mz4goc1su98x9f27wexvbo","title":"Claude Duet 主动智能体开启研究预览","summary":"我们听到了你们的反馈，希望 Claude 能主动替你们分担更多工作！Claude Duet 朝着这个方向迈出了一大步——它会注意到需要完成的工作，并在你开口之前就去做。\n\n在此加入等候名单：https://claude.com/product/claude-duet","sourceName":"X：Cat Wu（Anthropic，Claude Code 产品负责人） (@_catwu)","firstParty":false,"publishedAt":"2026-10-21T19:25:50.000Z","url":"https://x.com/_catwu/status/2112988751576330487"},{"id":"pb53dm6vvvow9ssb16whjqhn8","title":"Anthropic 预告主动智能体 Claude Duet，支持 Link、Shop Pay 结账与 1Password 登录","summary":"Anthropic 发布主动智能体 Claude Duet，作为独立研究预览应用上线，通过候补名单向美国 Pro 和 Max 订阅用户开放。该智能体基于 Claude Opus 5.5 构建，记忆、技能和已连接应用继承自用户的 Claude 账户。作者补充其可使用 Stripe 的 Link 数字钱包为企业采购、通过 Shopify 的 Shop Pay 在线上商店结账，并即将支持用 1Password 中保存的登录信息登录网站。","sourceName":"X：Testing Catalog (@testingcatalog)","firstParty":false,"publishedAt":"2026-10-21T19:25:34.000Z","url":"https://x.com/testingcatalog/status/2112988683628408852"},{"id":"sujogb2r68gyywjnb9qocou69","title":"Anthropic 发布主动式智能体 Claude Duet 研究预览版","summary":"Anthropic 发布 Claude Duet，一个主动式智能体，以独立研究预览应用形式提供。美国用户可通过 Pro 和 Max 计划的候补名单使用；该智能体围绕 Claude Opus 5.5 设计，可判断并决定用户需求，记忆、技能和连接的应用来自用户的 Claude 账户。","sourceName":"X：Testing Catalog (@testingcatalog)","firstParty":false,"publishedAt":"2026-10-21T19:15:11.000Z","url":"https://x.com/testingcatalog/status/2112986070874812923"},{"id":"cbed8d27akblrhboo7rgdjhvd","title":"Yuchen Jin 谈 Anthropic 开放研究预览的 Claude Duet 主动式智能体应用","summary":"Yuchen Jin 转引 Anthropic 官方消息并评论称 Claude Muse is coming。Anthropic 正在开放 Claude Duet 的研究预览，这是一个让 Claude 作为主动式智能体工作的应用，会主动提醒需要关注的事项、执行任务、在用户离开后继续工作，并在代替用户行动前先征得确认。作者评论自己手机上已装了 10 个个人智能体应用，还装得下这一个。","sourceName":"X：Yuchen Jin (@Yuchenj_UW)","firstParty":false,"publishedAt":"2026-10-21T19:11:35.000Z","url":"https://x.com/Yuchenj_UW/status/2112985163764466145"},{"id":"cgmgij8qjti0kg0xysuhy2hyt","title":"Claude 发布研究预览版 Claude Duet，以主动式智能体形态运作","summary":"Anthropic 的 Claude 官方账号宣布开放 Claude Duet 研究预览，这是一款让 Claude 作为主动式智能体工作的新应用。它会主动提示需要关注的事项，完成用户交办的任务，在用户离开后继续工作，并在代替用户行动前先向用户确认。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-10-21T19:09:35.000Z","url":"https://x.com/claudeai/status/2112984664256241837"},{"id":"jgg0i29t3o1eycc24c3wev0fx","title":"Anthropic 开启 Claude Duet 研究预览，Claude 以主动式智能体接管日常工作","summary":"Anthropic 开启 Claude Duet 研究预览，一款让 Claude 作为主动式智能体工作的独立应用，已登陆 iOS、Android 和 claude.ai，面向美国 Pro 和 Max 用户开放候补名单。","sourceName":"Claude：Blog（网页）","firstParty":true,"publishedAt":"2026-10-21T00:00:00.000Z","url":"https://claude.com/blog/claude-duet"},{"id":"m2z1twrs6k7t2ork1dffkf7ip","title":"Claude 向 Pro 和 Max 用户开放 Claude Duet 研究预览","summary":"Claude 于 10 月 21 日向 Pro 和 Max 套餐用户开放 Claude Duet 研究预览，这是一款让 Claude 以主动式智能体方式工作的新应用。官方提示更多信息可参见博客文章 Introducing Claude Duet。","sourceName":"Claude 应用发布说明","firstParty":true,"publishedAt":"2026-10-21T00:00:00.000Z","url":"https://support.claude.com/en/articles/12138966-release-notes#h_fdbb85f303"},{"id":"cig87wmqgnxxa9yiponz85una","title":"Vibe Check 评测 Claude Duet：Anthropic 的常驻个人智能体","summary":"Every 获得早期试用权限，评测 Anthropic 今日以研究预览形式推出的常驻个人智能体 Claude Duet。","sourceName":"Every：最新文章（网页）","firstParty":false,"publishedAt":"2026-10-20T16:00:00.000Z","url":"https://every.to/vibe-check/vibe-check-duet-anthropic-s-always-on-agent"},{"id":"oshpbnu9ga87g0jpeqwcl03l5","title":"Anthropic 开放 Claude Duet 研究预览：主动型智能体应用","summary":"Anthropic 开放 Claude Duet 研究预览，这是一款让 Claude 作为主动智能体工作的独立应用，提供 iOS、Android 和 claude.ai 版本，面向 Pro 和 Max 计划，首批面向美国用户，需加入等候名单。","sourceName":"Claude：Blog（网页）","firstParty":true,"publishedAt":"2026-10-20T16:00:00.000Z","url":"https://claude.com/resources/articles/claude-duet"}]},"a1acc180-e449-4e25-a658-0eb17993f729":{"publicId":"a1acc180-e449-4e25-a658-0eb17993f729","title":"Grok Bot 新增 Vault 保存登录与支付信息","status":"active","sourceCount":8,"reportCount":9,"firstReportAt":"2026-10-23T19:43:23.000Z","latestAt":"2026-10-24T02:40:37.000Z","latest":"Grok Bot 可保存登录信息与卡片","digest":"Grok Bot 新增信息保存功能：用户添加一次登录信息、银行卡和联系方式后，Bot 会记住这些信息，供日后自动填写。该功能随 grok @bot 0.75.5 稳定版逐步推送，更新日志中称其为“vault”；据 Testing Catalog 报道，保存的信息可在设置中新增的 Vault 标签页找到，功能正在移动端和桌面端应用中逐步推出。\n\nGrok Bot 称信息会被“安全地”保存，工程负责人 Lauren Tan 也称使用该功能“安全无忧”，设计负责人 Peng Zheng 以“保存一次，随时使用”宣传该功能，Elon Musk 称 Grok @Bot 将敏感信息保存在保险库中，但均未说明具体存储方式或安全机制。Cursor 的 Michael Truell 称通过 @Bot 可实现即时登录和结账，未说明这与信息保存功能的具体关系。","digestUpdatedAt":"2026-10-24T02:49:55.979Z","reports":[{"id":"hfv8wxjl2cnbi47f8xuon9p9i","title":"Grok Bot 可保存登录信息与卡片","summary":"能用 vaults 的话，谁还需要 1password 呢 👀","sourceName":"X：Larsen Cundric（自述加入 SpaceXSI，Grok Bot） (@larsencc)","firstParty":false,"publishedAt":"2026-10-24T02:40:37.000Z","url":"https://x.com/larsencc/status/2113822943750898094"},{"id":"u87h2a3mkaxwav6e1zps7fh02","title":"Grok Bot 可将敏感信息存入保险库","summary":"Grok @Bot 将敏感信息保存在保险库中","sourceName":"X：Elon Musk (@elonmusk, xAI)","firstParty":false,"publishedAt":"2026-10-24T00:54:17.000Z","url":"https://x.com/elonmusk/status/2113796183688982771"},{"id":"om9tutfmg2pp6lorahxo108ud","title":"Grok Bot 可保存登录与支付信息","summary":"保存一次，随时使用。少些重复，多些实干。🔐","sourceName":"X：Peng Zheng（SpaceXSI，Grok Bot 设计负责人） (@pengzheng_)","firstParty":false,"publishedAt":"2026-10-23T22:22:04.000Z","url":"https://x.com/pengzheng_/status/2113757876053536891"},{"id":"b9w167uhs8thjw2ipw12wouon","title":"Grok Bot 新增 Vault 存储登录信息","summary":"SPACEXSI 🔥：Grok Bot 现在有了自己的 Vault，用于存储登录信息、联系人和信用卡信息。\n\n保存的信息可在设置中新增的 Vault 标签页中找到。该功能正在移动端和桌面端应用中逐步推出。\n\nGrok Bot 正慢慢获得新的超能力！","sourceName":"X：Testing Catalog (@testingcatalog)","firstParty":false,"publishedAt":"2026-10-23T21:59:32.000Z","url":"https://x.com/testingcatalog/status/2113752209217474575"},{"id":"cb4uiaddxx9geprg9fl5jo9ia","title":"Grok Bot 0.75.5 稳定版发布","summary":"🚢🚢🚢","sourceName":"X：Lauren Tan（SpaceXSI，Grok Bot 工程负责人） (@poteto)","firstParty":false,"publishedAt":"2026-10-23T21:33:25.000Z","url":"https://x.com/poteto/status/2113745636382343364"},{"id":"f82vrimhxhoolr6e7u479zhb6","title":"Grok @bot 0.75.5 稳定版发布","summary":"grok @bot 0.75.5 现已稳定并逐步推送！\n\n- vault：保存登录信息、银行卡和联系人信息，你的 bot 会自动填写\n- bot 转发邮件时保留原始格式和附件\n- 你已要求的事项会减少审批卡片\n\n完整更新日志见下","sourceName":"X：Eric Zakariasson (@ericzakariasson)","firstParty":false,"publishedAt":"2026-10-23T21:24:33.000Z","url":"https://x.com/ericzakariasson/status/2113743401975963908"},{"id":"s8zguycxhvz2q4i0yh28396c9","title":"Cursor 支持 Bot 即时登录结账","summary":"通过 @Bot 实现即时登录和结账","sourceName":"X：Michael Truell (@mntruell)","firstParty":false,"publishedAt":"2026-10-23T21:05:54.000Z","url":"https://x.com/mntruell/status/2113738709799665905"},{"id":"buyz14jgqw2atvmad6dfdet1o","title":"Grok Bot 可保存登录与支付信息","summary":"用 Grok Bot，安全无忧！","sourceName":"X：Lauren Tan（SpaceXSI，Grok Bot 工程负责人） (@poteto)","firstParty":false,"publishedAt":"2026-10-23T20:04:29.000Z","url":"https://x.com/poteto/status/2113723252942241975"},{"id":"za67o778vzhmeybim74u0noya","title":"Grok Bot 新增保存登录与支付信息","summary":"Grok Bot 现在可以保存你的登录信息、银行卡和联系方式。\n\n添加一次，Bot 就会安全地记住它们，供日后使用。","sourceName":"X：Grok Bot (@bot)","firstParty":false,"publishedAt":"2026-10-23T19:43:23.000Z","url":"https://x.com/bot/status/2113717946019397910"}]}}};
